<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Hello Cube  EOroya Animate</title>
  <style>
    body { margin: 0; overflow: hidden; background: #1a1a2e; }
    canvas { display: block; }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>
  <script type="module" src="./main.ts"></script>
</body>
