```mermaid
graph TD
    A["Pointer event en SVGElement"] --> B["attachInteractiveListeners"]
    B --> C["createInteractionEvent"]
    C --> D["node.dispatchInteraction"]
    D --> E["node.emit('click', event)"]
    E --> F{"¿propagationStopped?"}
    F -->|"No"| G["parent.emit('click', event)"]
    F -->|"Sí"| H["Stop"]
    G --> F
```

